import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { SoftwarePackageService } from '../../services/software-package.service';
import { SoftwarePackageCardComponent } from '../../components/software-package-card/software-package-card.component';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-software-packages',
  templateUrl: './software-packages.component.html',
  styleUrls: ['./software-packages.component.css']
})
export class SoftwarePackagesComponent implements OnInit {
  searchQuery = '';
  selectedCategory = 'all';
  sortBy = 'title';
  sortOrder = 'asc';
  private searchTimeout: any;

  constructor(
    public router: Router,
    public softwarePackageService: SoftwarePackageService,
    public auth: AuthService
  ) {}

  ngOnInit(): void {
    this.auth.restoreSession();
    this.softwarePackageService.fetchCategories();
    this.softwarePackageService.fetchPackages();
  }

  get isAdmin(): boolean {
    return this.auth.isAdmin;
  }

  get rangeStart(): number {
    return (this.softwarePackageService.currentPage - 1) * this.softwarePackageService.itemsPerPage + 1;
  }

  get rangeEnd(): number {
    return Math.min(this.softwarePackageService.currentPage * this.softwarePackageService.itemsPerPage, this.softwarePackageService.total);
  }

  get visiblePages(): (number | string)[] {
    const total = this.softwarePackageService.totalPages;
    const current = this.softwarePackageService.currentPage;
    const pages: (number | string)[] = [];

    if (total <= 7) {
      for (let i = 1; i <= total; i++) {
        pages.push(i);
      }
    } else {
      pages.push(1);

      if (current > 3) {
        pages.push('...');
      }

      for (let i = Math.max(2, current - 1); i <= Math.min(total - 1, current + 1); i++) {
        pages.push(i);
      }

      if (current < total - 2) {
        pages.push('...');
      }

      pages.push(total);
    }

    return pages;
  }

  handleSearch(): void {
    clearTimeout(this.searchTimeout);
    this.searchTimeout = setTimeout(() => {
      this.softwarePackageService.setSearchQuery(this.searchQuery);
      this.softwarePackageService.fetchPackages();
    }, 500);
  }

  handleCategoryChange(): void {
    this.softwarePackageService.setCategory(this.selectedCategory);
    this.softwarePackageService.fetchPackages();
  }

  handleSortChange(): void {
    this.softwarePackageService.setSorting(this.sortBy, this.sortOrder);
    this.softwarePackageService.fetchPackages();
  }

  goToPage(page: number | string): void {
    if (page === '...' || typeof page !== 'number' || page < 1 || page > this.softwarePackageService.totalPages) {
      return;
    }
    this.softwarePackageService.setPage(page);
    this.softwarePackageService.fetchPackages();
  }

  viewPackage(pkg: SoftwarePackage): void {
    this.router.navigate(['/packages', pkg.id]);
  }

  goToAddPackage(): void {
    this.router.navigate(['/packages', 'new']);
  }

  formatCategory(category: string): string {
    return category
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="bg-white shadow-sm sticky top-0 z-10">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
      <div class="flex items-center justify-between">
        <div class="flex items-center gap-2">
          <div class="w-4 h-4 bg-primary rounded flex items-center justify-center">
            <svg class="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <h1 class="text-2xl font-bold text-primary">Otua Global Digital Solution</h1>
        </div>
        <nav class="hidden md:flex gap-6">
          <a routerLink="/packages" routerLinkActive="text-primary" class="font-medium text-gray-700 hover:text-primary transition-colors">Software Packages</a>
          <a routerLink="/packages/new" routerLinkActive="text-primary" class="font-medium text-gray-700 hover:text-primary transition-colors" *ngIf="isAdmin">Add Package</a>
          <a routerLink="/my-orders" routerLinkActive="text-primary" class="font-medium text-gray-700 hover:text-primary transition-colors">My Orders</a>
        </nav>
      </div>
    </div>
  </header>

  <main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
    <div class="mb-6 p-6 bg-blue-500 text-white rounded-xl shadow-lg">
      <h2 class="text-xl font-bold mb-2">🛒 Place an Order</h2>
      <p class="text-blue-100">Click the <strong>ORDER NOW</strong> button on any software package card to place your order.</p>
    </div>

    <div class="mb-6 space-y-4">
      <div class="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
        <div class="flex-1 w-full sm:max-w-md">
          <div class="relative">
            <input [(ngModel)]="searchQuery" (input)="handleSearch()" type="text" placeholder="Search software packages..." class="input-field pl-10" />
            <svg class="w-5 h-5 text-gray-400 absolute left-3 top-1/2 transform -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
        </div>

        <button (click)="goToAddPackage()" class="btn-primary whitespace-nowrap w-full sm:w-auto" *ngIf="isAdmin">
          <svg class="w-5 h-5 inline-block mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4" />
          </svg>
          Add Package
        </button>
      </div>

      <div class="flex flex-col sm:flex-row gap-4">
        <select [(ngModel)]="selectedCategory" (change)="handleCategoryChange()" class="input-field">
          <option value="all">All Categories</option>
          <option *ngFor="let category of softwarePackageService.categories" [value]="category">{{ formatCategory(category) }}</option>
        </select>

        <select [(ngModel)]="sortBy" (change)="handleSortChange()" class="input-field">
          <option value="title">Sort by Title</option>
          <option value="price">Sort by Price</option>
          <option value="rating">Sort by Rating</option>
        </select>

        <select [(ngModel)]="sortOrder" (change)="handleSortChange()" class="input-field">
          <option value="asc">Ascending</option>
          <option value="desc">Descending</option>
        </select>
      </div>

      <div *ngIf="!softwarePackageService.isLoading && softwarePackageService.packages.length > 0" class="text-sm text-gray-600">
        Showing {{ rangeStart }} - {{ rangeEnd }} of {{ softwarePackageService.total }} software packages
      </div>
    </div>

    <div *ngIf="softwarePackageService.isLoading" class="text-center py-12">
      <div class="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      <p class="mt-4 text-gray-600">Loading software packages...</p>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && softwarePackageService.error" class="text-center py-12">
      <div class="text-red-500 mb-4">
        <svg class="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-red-600">{{ softwarePackageService.error }}</p>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && !softwarePackageService.error && softwarePackageService.packages.length > 0" class="space-y-6">
      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        <app-software-package-card *ngFor="let pkg of softwarePackageService.packages" [package]="pkg" (click)="viewPackage(pkg)"></app-software-package-card>
      </div>

      <div *ngIf="softwarePackageService.totalPages > 1" class="flex justify-center items-center gap-2 mt-8">
        <button (click)="goToPage(softwarePackageService.currentPage - 1)" [disabled]="softwarePackageService.currentPage === 0" class="btn-secondary">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" />
          </svg>
        </button>

        <div class="flex gap-1">
          <button *ngFor="let page of visiblePages" (click)="goToPage(page)"
            [ngClass]="{
              'bg-primary text-white': page === softwarePackageService.currentPage,
              'bg-white text-gray-700 hover:bg-gray-100': page !== softwarePackageService.currentPage
            }"
            class="px-4 py-2 rounded-lg font-medium transition-colors">
            {{ page }}
          </button>
        </div>

        <button (click)="goToPage(softwarePackageService.currentPage + 1)" [disabled]="softwarePackageService.currentPage === softwarePackageService.totalPages - 1" class="btn-secondary">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7" />
          </svg>
        </button>
      </div>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && !softwarePackageService.error && softwarePackageService.packages.length === 0" class="text-center py-12">
      <svg class="w-16 h-16 mx-auto text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
      </svg>
      <p class="text-gray-600">No software packages found</p>
      <p class="text-gray-500 text-sm mt-2">Try adjusting your search or filter</p>
    </div>
  </main>
</div>
